-- Reajuste de preços para a inauguração (aumento de 11,12% arredondado para cima no centavo).
-- Com o cupom de 10%, o cliente paga exatamente o preço anterior.
-- Altera SOMENTE mn_products.sale_cents (e updated_at) dos produtos já salvos pelo painel.
-- Produtos nunca editados no painel usam o catálogo do código e já recebem o reajuste com a implantação.
-- Cada linha só muda se o preço gravado ainda for o anterior ao reajuste: importar de novo não aplica o aumento duas vezes
-- e não altera preços que a loja já tenha mudado no painel depois da implantação.
-- Produtos criados no painel (custom-...) não estão incluídos: ajuste-os no próprio painel.
-- Granel: sale_cents fica em centavos por kg (a vitrine mostra por 100 g). Unidade: centavos por unidade.

START TRANSACTION;
SET @mn_agora = ROUND(UNIX_TIMESTAMP(NOW(3)) * 1000);

INSERT INTO mn_audit(event,entity_id,details,created_at) SELECT 'product.price_raise', id, '{"previousPriceCents":7799,"priceCents":8666,"source":"reajuste inauguração"}', @mn_agora FROM mn_products WHERE id='prod-1' AND is_bulk=0 AND sale_cents=7799;
UPDATE mn_products SET sale_cents=8666, updated_at=@mn_agora WHERE id='prod-1' AND is_bulk=0 AND sale_cents=7799;
